raws:
{
  "pick": 0,
  "name_zh": "寒霜連環擊",
  "concept": "在寒氣中不斷堆疊的力量，最終引發劇烈的凍結與毒素侵蝕。",
  "cast_flavor": "隨著每一次揮動，空氣中凝結的冰晶將化作致命的瘴氣。"
}

{
  "pick": 0,
  "name_zh": "寒霜之隙",
  "concept": "利用極寒與毒素的交織，在敵方身邊堆疊連綿的壓迫感。",
  "cast_flavor": "冰晶與瘴氣在空氣中糾纏，隨著節奏不斷凝聚。"
}

{
  "pick": 0,
  "name_zh": "裂地重擊",
  "concept": "將積蓄的怒火轉化為大地崩裂的力量。",
  "cast_flavor": "隨著怒火噴湧，法器敲擊地面引發劇烈的震顫。"
}

{
  "pick": 1,
  "name_zh": "暗影縛結",
  "concept": "在目標身上植入不穩定的陰影核心，隨後引發劇烈的爆裂。",
  "cast_flavor": "影子在目標皮肉下瘋狂蠕動，最終伴隨刺耳的碎裂聲炸裂開來。"
}

{
  "pick": 0,
  "name_zh": "霜結撞擊",
  "concept": "將寒氣凝結於指尖，伴隨寒冰的重量猛烈衝擊目標。",
  "cast_flavor": "寒霜在碰撞的瞬間凝固，將敵人的軀殼封入冰層中。"
}

{
  "pick": 0,
  "name_zh": "刃紋印記",
  "concept": "在目標周圍刻下不穩定的切割線條，使其防禦變得脆弱。",
  "cast_flavor": "武器劃過空氣，留下一圈無法磨滅的缺口。"
}

{
  "pick": 0,
  "name_zh": "深淵墜落",
  "concept": "利用目標身上的標記引發暗影坍塌，將敵人重重擊倒。",
  "cast_flavor": "法器中湧出的暗影如黑洞般張開，將一切光亮吞噬並重壓而下。"
}

{
  "pick": 0,
  "name_zh": "暗影重壓",
  "concept": "藉由目標身上的標記引發暗影傾瀉，將敵人擊倒在地。",
  "cast_flavor": "法器中湧出的暗影如墨色重擔，將目標壓向地面。"
}

{
  "pick": 2,
  "name_zh": "迴旋風壓",
  "concept": "引動空氣流動的軌跡，擴散周遭的氣息。",
  "cast_flavor": "隨著法器輕轉，流動的氣流將四周的物質向外推擠。"
}

{
  "pick": 1,
  "name_zh": "狂風拓界",
  "concept": "自高處俯衝而下，掀起足以擴散火種的強大氣流。",
  "cast_flavor": "法器在掌心震盪，帶動空氣激盪出灼熱的風壓。"
}

{
  "pick": 0,
  "name_zh": "幽暗之墜",
  "concept": "藉由消耗自身專注，將暗影化作沉重的重壓。",
  "cast_flavor": "黑暗從高處傾瀉而下，將目標徹底壓入塵土之中。"
}

{
  "pick": 0,
  "name_zh": "幽暗之墜",
  "concept": "將內心的專注轉化為無盡的黑暗，使對手無法起身。",
  "cast_flavor": "濃稠的暗影如潮水般傾瀉，將目標沒入黑暗之中。"
}

{
  "pick": 0,
  "name_zh": "雷霆之紋",
  "concept": "在空間中留下跳躍的電光符文，隨後引發刺耳的電擊。",
  "cast_flavor": "指尖划過空氣，空氣中綻放出刺眼的藍白火花。"
}

{
  "pick": 3,
  "name_zh": "蠻荒推力",
  "concept": "藉由武器的勢能將敵人向後撥開。",
  "cast_flavor": "藉由揮舞重物帶來的衝擊力，強行切斷對方的站位。"
}

{
  "pick": 0,
  "name_zh": "俯瞰之光",
  "concept": "從制高點投射出的神聖裁決。",
  "cast_flavor": "當你立於高處，神聖的光輝將隨著箭矢一同降臨。"
}

{
  "pick": 1,
  "name_zh": "雷光之標",
  "concept": "透過法器引導閃電在目標身上留下無法擺脫的導電路徑。",
  "cast_flavor": "閃光在空氣中炸裂，將目標鎖定在電弧的縫隙之中。"
}

{
  "pick": 1,
  "name_zh": "獵影之眼",
  "concept": "在暗處鎖定目標並在射擊後於敵身上留下無法擺脫的印記。",
  "cast_flavor": "箭簇劃破空氣，將獵物的命運徹底釘在你的視線之中。"
}

{
  "pick": 2,
  "name_zh": "掠奪之眼",
  "concept": "透視敵方防線並強行奪取其身上的益處。",
  "cast_flavor": "目光鎖定目標，將對方的加持轉化為自身的助力。"
}

{
  "pick": 0,
  "name_zh": "聖光威懾",
  "concept": "透過釋放純淨的輝光使敵人陷入恐懼與混亂。",
  "cast_flavor": "法器迸發出的光芒迫使敵人不得不正面迎擊施法者。"
}

{
  "pick": 0,
  "name_zh": "神聖威懾",
  "concept": "透過純淨的輝光吸引敵人的注意力。",
  "cast_flavor": "法器迸發出的光芒迫使敵人不得不正面迎擊施法者。"
}

{
  "pick": 0,
  "name_zh": "寂靜之息",
  "concept": "將所有的專注凝聚於尖端，在迸發的瞬間封閉敵人的聲音。",
  "cast_flavor": "隨著呼吸止息，這股無聲的衝擊將撕裂空氣。"
}

{
  "pick": 0,
  "name_zh": "暗影連擊之終",
  "concept": "將隱藏在陰影中的鋒利氣息，轉化為毀滅性的爆發力。",
  "cast_flavor": "隨著連續的進攻，黑暗在刃尖匯聚並猛然迸發。"
}

{
  "pick": 1,
  "name_zh": "火光盈動",
  "concept": "將體內積蓄的氣息轉化為熾熱的火焰。 ",
  "cast_flavor": "指尖躍出的火光在空氣中炸裂，將周遭的氣息點燃。"
}

{
  "pick": 1,
  "name_zh": "火光盈動",
  "concept": "將體內積蓄的氣息轉化為躍動的火焰",
  "cast_flavor": "指尖湧出的火光在空氣中炸裂，伴隨著微弱的虛弱感。"
}

{
  "pick": 0,
  "name_zh": "灼痕之紋",
  "concept": "在受創的土地上留下一道灼熱的印記。",
  "cast_flavor": "揮動武器劃過，讓地面留下燙手的紅光。"
}

{
  "pick": 1,
  "name_zh": "煙幕環繞",
  "concept": "引燃空氣中的微粒並製造遮蔽物。",
  "cast_flavor": "火焰在空氣中炸裂，隨即被濃厚的灰白煙雲所吞噬。"
}

{
  "pick": 1,
  "name_zh": "煙雲迴旋",
  "concept": "在目標周遭引發火光並籠罩厚重的灰白煙霧。",
  "cast_flavor": "烈焰在環形軌跡中炸裂，隨即被濃密的煙雲所吞噬。"
}

{
  "pick": 0,
  "name_zh": "微風療癒",
  "concept": "利用流動的氣流緩解受創的傷口。",
  "cast_flavor": "輕柔的風掠過身側，撫平了撕裂的痛楚。"
}

{
  "pick": 0,
  "name_zh": "寒意怒火",
  "concept": "受創時會釋放出冰冷的憤怒並積累怒氣。",
  "cast_flavor": "冰層在受傷的部位迅速擴張，並轉化為壓抑的怒意。"
}

{
  "pick": 4,
  "name_zh": "腐蝕之刃紋",
  "concept": "將致命的毒素編織進武器的刻痕之中。",
  "cast_flavor": "刀鋒劃過空氣，留下的紋路滲出暗淡的紫煙。"
}
